     !> SSB2ST_KERNELS: is an internal routine used by the SSYTRD_SB2ST
     !> subroutine.

     pure subroutine la_ssb2st_kernels(uplo,wantz,ttype,st,ed,sweep,n,nb,ib,a,lda, &
               v,tau,ldvt,work)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           logical(lk),intent(in) :: wantz
           integer(ilp),intent(in) :: ttype,st,ed,sweep,n,nb,ib,lda,ldvt
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: v(*),tau(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i,j1,j2,lm,ln,vpos,taupos,dpos,ofdpos,ajeter
           real(sp) :: ctmp
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ajeter = ib + ldvt
           upper = la_lsame(uplo,'U')
           if (upper) then
               dpos = 2*nb + 1
               ofdpos = 2*nb
           else
               dpos = 1
               ofdpos = 2
           end if
           ! upper case
           if (upper) then
               if (wantz) then
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               else
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               end if
               if (ttype == 1) then
                   lm = ed - st + 1
                   v(vpos) = one
                   do i = 1,lm - 1
                       v(vpos + i) = (a(ofdpos - i,st + i))
                       a(ofdpos - i,st + i) = zero
                   end do
                   ctmp = (a(ofdpos,st))
                   call la_slarfg(lm,ctmp,v(vpos + 1),1,tau(taupos))
                   a(ofdpos,st) = ctmp
                   lm = ed - st + 1
                   call la_slarfy(uplo,lm,v(vpos),1, (tau(taupos)),a(dpos,st), &
                             lda - 1,work)
               end if
               if (ttype == 3) then
                   lm = ed - st + 1
                   call la_slarfy(uplo,lm,v(vpos),1, (tau(taupos)),a(dpos,st), &
                             lda - 1,work)
               end if
               if (ttype == 2) then
                   j1 = ed + 1
                   j2 = min(ed + nb,n)
                   ln = ed - st + 1
                   lm = j2 - j1 + 1
                   if (lm > 0) then
                       call la_slarfx('LEFT',ln,lm,v(vpos), (tau(taupos)),a(dpos - nb, &
                                  j1),lda - 1,work)
                       if (wantz) then
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       else
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       end if
                       v(vpos) = one
                       do i = 1,lm - 1
                           v(vpos + i) = (a(dpos - nb - i,j1 + i))
                           a(dpos - nb - i,j1 + i) = zero
                       end do
                       ctmp = (a(dpos - nb,j1))
                       call la_slarfg(lm,ctmp,v(vpos + 1),1,tau(taupos))
                       a(dpos - nb,j1) = ctmp
                       call la_slarfx('RIGHT',ln - 1,lm,v(vpos),tau(taupos),a(dpos - nb + &
                                 1,j1),lda - 1,work)
                   end if
               end if
           ! lower case
           else
               if (wantz) then
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               else
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               end if
               if (ttype == 1) then
                   lm = ed - st + 1
                   v(vpos) = one
                   do i = 1,lm - 1
                       v(vpos + i) = a(ofdpos + i,st - 1)
                       a(ofdpos + i,st - 1) = zero
                   end do
                   call la_slarfg(lm,a(ofdpos,st - 1),v(vpos + 1),1,tau(taupos))

                   lm = ed - st + 1
                   call la_slarfy(uplo,lm,v(vpos),1, (tau(taupos)),a(dpos,st), &
                             lda - 1,work)
               end if
               if (ttype == 3) then
                   lm = ed - st + 1
                   call la_slarfy(uplo,lm,v(vpos),1, (tau(taupos)),a(dpos,st), &
                             lda - 1,work)
               end if
               if (ttype == 2) then
                   j1 = ed + 1
                   j2 = min(ed + nb,n)
                   ln = ed - st + 1
                   lm = j2 - j1 + 1
                   if (lm > 0) then
                       call la_slarfx('RIGHT',lm,ln,v(vpos),tau(taupos),a(dpos + nb, &
                                 st),lda - 1,work)
                       if (wantz) then
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       else
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       end if
                       v(vpos) = one
                       do i = 1,lm - 1
                           v(vpos + i) = a(dpos + nb + i,st)
                           a(dpos + nb + i,st) = zero
                       end do
                       call la_slarfg(lm,a(dpos + nb,st),v(vpos + 1),1,tau(taupos))

                       call la_slarfx('LEFT',lm,ln - 1,v(vpos), (tau(taupos)),a(dpos + &
                                 nb - 1,st + 1),lda - 1,work)
                   end if
               end if
           end if
           return
     end subroutine la_ssb2st_kernels
