           ! determine the block size, the workspace size and the hous size.
           ib = la_ilaenv2stage(2,'SSYTRD_SB2ST',vect,n,kd,-1,-1)
           lhmin = la_ilaenv2stage(3,'SSYTRD_SB2ST',vect,n,kd,ib,-1)
           lwmin = la_ilaenv2stage(4,'SSYTRD_SB2ST',vect,n,kd,ib,-1)
           if (.not. afters1 .and. .not. la_lsame(stage1,'N')) then
              info = -1
           else if (.not. la_lsame(vect,'N')) then
              info = -2
           else if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (kd < 0) then
              info = -5
           else if (ldab < (kd + 1)) then
              info = -7
           else if (lhous < lhmin .and. .not. lquery) then
              info = -11
           else if (lwork < lwmin .and. .not. lquery) then
              info = -13
           end if
           if (info == 0) then
              hous(1) = lhmin
              work(1) = lwmin
           end if
           if (info /= 0) then
              call la_xerbla('SSYTRD_SB2ST',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) then
               hous(1) = 1
               work(1) = 1
               return
           end if
           ! determine pointer position
           ldv = kd + ib
           sizetau = 2*n
           sisev = 2*n
           indtau = 1
           indv = indtau + sizetau
           lda = 2*kd + 1
           sizea = lda*n
           inda = 1
           indw = inda + sizea
           nthreads = 1
           tid = 0
           if (upper) then
               apos = inda + kd
               awpos = inda
               dpos = apos + kd
               ofdpos = dpos - 1
               abdpos = kd + 1
               abofdpos = kd
           else
               apos = inda
               awpos = inda + kd + 1
               dpos = apos
               ofdpos = dpos + 1
               abdpos = 1
               abofdpos = 2
           end if
