           thgrsiz = n
           grsiz = 1
           shift = 3
           nbtiles = ceiling(real(n,KIND=sp)/real(kd,KIND=sp))
           stepercol = ceiling(real(shift,KIND=sp)/real(grsiz,KIND=sp))
