                                   edind = min(colpt,n)
                                   blklastind = colpt
                               else
                                   colpt = ((myid + 1)/2)*kd + sweepid
                                   stind = colpt - kd + 1
                                   edind = min(colpt,n)
                                   if ((stind >= edind - 1) .and. (edind == n)) then
                                       blklastind = n
                                   else
                                       blklastind = 0
                                   end if
                               end if
