              do i = 2,n
                 a(i,1) = zero
              end do
              if (n > 1) then
                 ! generate q(2:n,2:n)
                 call la_dorgqr(n - 1,n - 1,n - 1,a(2,2),lda,tau,work,lwork,iinfo)

              end if
