                    w(j) = tmp1
                    iwork(indibl + j - 1) = itmp1
                    call la_dswap(n,z(1,i),1,z(1,j),1)
                    if (info /= 0) then
                       itmp1 = ifail(i)
                       ifail(i) = ifail(j)
                       ifail(j) = itmp1
