           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = sqrt(bignum)
           ! scale matrix to allowable range, if necessary.
           anrm = la_qlansp('M',uplo,n,ap,work)
           iscale = 0
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
