              info = -9
           end if
           if (info == 0) then
              if (n <= 1) then
                 liwmin = 1
                 lwmin = 1
              else
                 if (wantz) then
                    liwmin = 3 + 5*n
                    lwmin = 1 + 6*n + 2*n**2
                 else
                    liwmin = 1
                    lwmin = 2*n
                 end if
              end if
              work(1) = lwmin
              iwork(1) = liwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -11
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -13
              end if
           end if
           if (info /= 0) then
              call la_xerbla('QSPGVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! form a cholesky factorization of bp.
           call la_qpptrf(uplo,n,bp,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem and solve.
           call la_qspgst(itype,uplo,n,ap,bp,info)
           call la_qspevd(jobz,uplo,n,ap,w,z,ldz,work,lwork,iwork,liwork,info)

           lwmin = max(real(lwmin,KIND=qp),real(work(1),KIND=qp))
           liwmin = max(real(liwmin,KIND=qp),real(iwork(1),KIND=qp))
           if (wantz) then
              ! backtransform eigenvectors to the original problem.
              neig = n
              if (info > 0) neig = info - 1
              if (itype == 1 .or. itype == 2) then
                 ! for a*x=(lambda)*b*x and a*b*x=(lambda)*x;
                 ! backtransform eigenvectors: x = inv(l)**t *y or inv(u)*y
                 if (upper) then
                    trans = 'N'
                 else
                    trans = 'T'
                 end if
                 do j = 1,neig
                    call la_qtpsv(uplo,trans,'NON-UNIT',n,bp,z(1,j),1)
                 end do
              else if (itype == 3) then
                 ! for b*a*x=(lambda)*x;
                 ! backtransform eigenvectors: x = l*y or u**t *y
                 if (upper) then
                    trans = 'T'
                 else
                    trans = 'N'
                 end if
                 do j = 1,neig
                    call la_qtpmv(uplo,trans,'NON-UNIT',n,bp,z(1,j),1)
                 end do
              end if
           end if
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qspgvd
#endif

     !> SSYEVR: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric matrix A.  Eigenvalues and eigenvectors can be
     !> selected by specifying either a range of values or a range of
     !> indices for the desired eigenvalues.
     !> SSYEVR first reduces the matrix A to tridiagonal form T with a call
     !> to SSYTRD.  Then, whenever possible, SSYEVR calls SSTEMR to compute
     !> the eigenspectrum using Relatively Robust Representations.  SSTEMR
     !> computes eigenvalues by the dqds algorithm, while orthogonal
     !> eigenvectors are computed from various "good" L D L^T representations
     !> (also known as Relatively Robust Representations). Gram-Schmidt
     !> orthogonalization is avoided as far as possible. More specifically,
     !> the various steps of the algorithm are as follows.
     !> For each unreduced block (submatrix) of T,
     !> (a) Compute T - sigma I  = L D L^T, so that L and D
     !> define all the wanted eigenvalues to high relative accuracy.
     !> This means that small relative changes in the entries of D and L
     !> cause only small relative changes in the eigenvalues and
     !> eigenvectors. The standard (unfactored) representation of the
     !> tridiagonal matrix T does not have this property in general.
     !> (b) Compute the eigenvalues to suitable accuracy.
     !> If the eigenvectors are desired, the algorithm attains full
     !> accuracy of the computed eigenvalues only right before
     !> the corresponding vectors have to be computed, see steps c) and d).
     !> (c) For each cluster of close eigenvalues, select a new
     !> shift close to the cluster, find a new factorization, and refine
     !> the shifted eigenvalues to suitable accuracy.
     !> (d) For each eigenvalue with a large enough relative separation compute
     !> the corresponding eigenvector by forming a rank revealing twisted
     !> factorization. Go back to (c) for any clusters that remain.
     !> The desired accuracy of the output can be specified by the input
     !> parameter ABSTOL.
     !> For more details, see SSTEMR's documentation and:
     !> - Inderjit S. Dhillon and Beresford N. Parlett: "Multiple representations
     !> to compute orthogonal eigenvectors of symmetric tridiagonal matrices,"
     !> Linear Algebra and its Applications, 387(1), pp. 1-28, August 2004.
     !> - Inderjit Dhillon and Beresford Parlett: "Orthogonal Eigenvectors and
     !> Relative Gaps," SIAM Journal on Matrix Analysis and Applications, Vol. 25,
     !> 2004.  Also LAPACK Working Note 154.
     !> - Inderjit Dhillon: "A new O(n^2) algorithm for the symmetric
     !> tridiagonal eigenvalue/eigenvector problem",
     !> Computer Science Division Technical Report No. UCB/CSD-97-971,
     !> UC Berkeley, May 1997.
     !> Note 1 : SSYEVR calls SSTEMR when the full spectrum is requested
     !> on machines which conform to the ieee-754 floating point standard.
     !> SSYEVR calls SSTEBZ and SSTEIN on non-ieee machines and
     !> when partial spectrum requests are made.
     !> Normal execution of SSTEMR may create NaNs and infinities and
     !> hence may abort due to a floating point exception in environments
     !> which do not handle NaNs and infinities in the ieee standard default
     !> manner.

     subroutine la_ssyevr(jobz,range,uplo,n,a,lda,vl,vu,il,iu,abstol,m,w,z,ldz, &
               isuppz,work,lwork,iwork,liwork,info)
        use la_constants_sp,only:zero,one,two
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,iu,lda,ldz,liwork,lwork,n
           integer(ilp),intent(out) :: info,m
           real(sp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: isuppz(*),iwork(*)
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: w(*),work(*),z(ldz,*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,lower,lquery,test,valeig,wantz,tryrac
           character :: order
           integer(ilp) :: i,ieeeok,iinfo,imax,indd,inddd,inde,indee,indibl,indifl, &
           indisp,indiwo,indtau,indwk,indwkn,iscale,j,jj,liwmin,llwork,llwrkn,lwkopt, &
                     lwmin,nb,nsplit
           real(sp) :: abstll,anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           ieeeok = la_ilaenv(10,'SSYEVR','N',1,2,3,4)
           lower = la_lsame(uplo,'L')
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lquery = ((lwork == -1) .or. (liwork == -1))
           lwmin = max(1,26*n)
           liwmin = max(1,10*n)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -8
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -9
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -10
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -15
              end if
           end if
           if (info == 0) then
              nb = la_ilaenv(1,'SSYTRD',uplo,n,-1,-1,-1)
              nb = max(nb,la_ilaenv(1,'SORMTR',uplo,n,-1,-1,-1))
              lwkopt = max((nb + 1)*n,lwmin)
              work(1) = lwkopt
              iwork(1) = liwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -18
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -20
              end if
           end if
           if (info /= 0) then
              call la_xerbla('SSYEVR',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) then
              work(1) = 1
              return
           end if
           if (n == 1) then
              work(1) = 26
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = a(1,1)
              else
                 if (vl < a(1,1) .and. vu >= a(1,1)) then
                    m = 1
                    w(1) = a(1,1)
                 end if
              end if
              if (wantz) then
                 z(1,1) = one
                 isuppz(1) = 1
                 isuppz(2) = 1
              end if
              return
           end if
           ! get machine constants.
           safmin = la_slamch('SAFE MINIMUM')
           eps = la_slamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           abstll = abstol
           if (valeig) then
              vll = vl
              vuu = vu
           end if
           anrm = la_slansy('M',uplo,n,a,lda,work)
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              if (lower) then
                 do j = 1,n
                    call la_sscal(n - j + 1,sigma,a(j,j),1)
                 end do
              else
                 do j = 1,n
                    call la_sscal(j,sigma,a(1,j),1)
                 end do
              end if
              if (abstol > 0) abstll = abstol*sigma
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! initialize indices into workspaces.  note: the iwork indices are
           ! used only if la_ssterf or la_sstemr fail.
           ! work(indtau:indtau+n-1) stores the scalar factors of the
           ! elementary reflectors used in la_ssytrd.
           indtau = 1
           ! work(indd:indd+n-1) stores the tridiagonal's diagonal entries.
           indd = indtau + n
           ! work(inde:inde+n-1) stores the off-diagonal entries of the
           ! tridiagonal matrix from la_ssytrd.
           inde = indd + n
           ! work(inddd:inddd+n-1) is a copy of the diagonal entries over
           ! -written by la_sstemr (the la_ssterf path copies the diagonal to w).
           inddd = inde + n
           ! work(indee:indee+n-1) is a copy of the off-diagonal entries over
           ! -written while computing the eigenvalues in la_ssterf and la_sstemr.
           indee = inddd + n
           ! indwk is the starting offset of the left-over workspace, and
           ! llwork is the remaining workspace size.
           indwk = indee + n
           llwork = lwork - indwk + 1
           ! iwork(indibl:indibl+m-1) corresponds to iblock in la_sstebz and
           ! stores the block indices of each of the m<=n eigenvalues.
           indibl = 1
           ! iwork(indisp:indisp+nsplit-1) corresponds to isplit in la_sstebz and
           ! stores the starting and finishing indices of each block.
           indisp = indibl + n
           ! iwork(indifl:indifl+n-1) stores the indices of eigenvectors
           ! that corresponding to eigenvectors that fail to converge in
           ! la_sstein.  this information is discarded; if any fail, the driver
           ! returns info > 0.
           indifl = indisp + n
           ! indiwo is the offset of the remaining integer workspace.
           indiwo = indifl + n
           ! call la_ssytrd to reduce symmetric matrix to tridiagonal form.
           call la_ssytrd(uplo,n,a,lda,work(indd),work(inde),work(indtau),work( &
                     indwk),llwork,iinfo)
           ! if all eigenvalues are desired
           ! then call la_ssterf or la_sstemr and la_sormtr.
           test = .false.
           if (indeig) then
              if (il == 1 .and. iu == n) then
                 test = .true.
              end if
           end if
           if ((alleig .or. test) .and. (ieeeok == 1)) then
              if (.not. wantz) then
                 call la_scopy(n,work(indd),1,w,1)
                 call la_scopy(n - 1,work(inde),1,work(indee),1)
                 call la_ssterf(n,w,work(indee),info)
              else
                 call la_scopy(n - 1,work(inde),1,work(indee),1)
                 call la_scopy(n,work(indd),1,work(inddd),1)
                 if (abstol <= two*n*eps) then
                    tryrac = .true.
                 else
                    tryrac = .false.
                 end if
                 call la_sstemr(jobz,'A',n,work(inddd),work(indee),vl,vu,il,iu,m, &
                            w,z,ldz,n,isuppz,tryrac,work(indwk),lwork,iwork,liwork,info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_sstemr.
                 if (wantz .and. info == 0) then
                    indwkn = inde
                    llwrkn = lwork - indwkn + 1
                    call la_sormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                               indwkn),llwrkn,iinfo)
                 end if
              end if
              if (info == 0) then
                 ! everything worked.  skip la_sstebz/la_sstein.  iwork(:) are
                 ! undefined.
                 m = n
                 go to 30
              end if
              info = 0
           end if
           ! otherwise, call la_sstebz and, if eigenvectors are desired, la_sstein.
           ! also call la_sstebz and la_sstein if la_sstemr fails.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           call la_sstebz(range,order,n,vll,vuu,il,iu,abstll,work(indd),work(inde &
           ),m,nsplit,w,iwork(indibl),iwork(indisp),work(indwk),iwork(indiwo),info)

           if (wantz) then
              call la_sstein(n,work(indd),work(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,work(indwk),iwork(indiwo),iwork(indifl),info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_sstein.
              indwkn = inde
              llwrkn = lwork - indwkn + 1
              call la_sormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                        indwkn),llwrkn,iinfo)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
        ! jump here if la_sstemr/la_sstein succeeded.
        30 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_sscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.  note: we do not sort the ifail portion of iwork.
           ! it may not be initialized (if la_sstemr/la_sstein succeeded), and we do
           ! not return this detailed information to the user.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    w(i) = w(j)
                    w(j) = tmp1
                    call la_sswap(n,z(1,i),1,z(1,j),1)
                 end if
              end do
           end if
           ! set work(1) to optimal workspace size.
           work(1) = lwkopt
           iwork(1) = liwmin
           return
     end subroutine la_ssyevr
     !> DSYEVR: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric matrix A.  Eigenvalues and eigenvectors can be
     !> selected by specifying either a range of values or a range of
     !> indices for the desired eigenvalues.
     !> DSYEVR first reduces the matrix A to tridiagonal form T with a call
     !> to DSYTRD.  Then, whenever possible, DSYEVR calls DSTEMR to compute
     !> the eigenspectrum using Relatively Robust Representations.  DSTEMR
     !> computes eigenvalues by the dqds algorithm, while orthogonal
     !> eigenvectors are computed from various "good" L D L^T representations
     !> (also known as Relatively Robust Representations). Gram-Schmidt
     !> orthogonalization is avoided as far as possible. More specifically,
     !> the various steps of the algorithm are as follows.
     !> For each unreduced block (submatrix) of T,
     !> (a) Compute T - sigma I  = L D L^T, so that L and D
     !> define all the wanted eigenvalues to high relative accuracy.
     !> This means that small relative changes in the entries of D and L
     !> cause only small relative changes in the eigenvalues and
     !> eigenvectors. The standard (unfactored) representation of the
     !> tridiagonal matrix T does not have this property in general.
     !> (b) Compute the eigenvalues to suitable accuracy.
     !> If the eigenvectors are desired, the algorithm attains full
     !> accuracy of the computed eigenvalues only right before
     !> the corresponding vectors have to be computed, see steps c) and d).
     !> (c) For each cluster of close eigenvalues, select a new
     !> shift close to the cluster, find a new factorization, and refine
     !> the shifted eigenvalues to suitable accuracy.
     !> (d) For each eigenvalue with a large enough relative separation compute
     !> the corresponding eigenvector by forming a rank revealing twisted
     !> factorization. Go back to (c) for any clusters that remain.
     !> The desired accuracy of the output can be specified by the input
     !> parameter ABSTOL.
     !> For more details, see DSTEMR's documentation and:
     !> - Inderjit S. Dhillon and Beresford N. Parlett: "Multiple representations
     !> to compute orthogonal eigenvectors of symmetric tridiagonal matrices,"
     !> Linear Algebra and its Applications, 387(1), pp. 1-28, August 2004.
     !> - Inderjit Dhillon and Beresford Parlett: "Orthogonal Eigenvectors and
     !> Relative Gaps," SIAM Journal on Matrix Analysis and Applications, Vol. 25,
     !> 2004.  Also LAPACK Working Note 154.
     !> - Inderjit Dhillon: "A new O(n^2) algorithm for the symmetric
     !> tridiagonal eigenvalue/eigenvector problem",
     !> Computer Science Division Technical Report No. UCB/CSD-97-971,
     !> UC Berkeley, May 1997.
     !> Note 1 : DSYEVR calls DSTEMR when the full spectrum is requested
     !> on machines which conform to the ieee-754 floating point standard.
     !> DSYEVR calls DSTEBZ and DSTEIN on non-ieee machines and
     !> when partial spectrum requests are made.
     !> Normal execution of DSTEMR may create NaNs and infinities and
     !> hence may abort due to a floating point exception in environments
     !> which do not handle NaNs and infinities in the ieee standard default
     !> manner.

     subroutine la_dsyevr(jobz,range,uplo,n,a,lda,vl,vu,il,iu,abstol,m,w,z,ldz, &
               isuppz,work,lwork,iwork,liwork,info)
        use la_constants_dp,only:zero,one,two
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,iu,lda,ldz,liwork,lwork,n
           integer(ilp),intent(out) :: info,m
           real(dp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: isuppz(*),iwork(*)
           real(dp),intent(inout) :: a(lda,*)
           real(dp),intent(out) :: w(*),work(*),z(ldz,*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,lower,lquery,valeig,wantz,tryrac
           character :: order
           integer(ilp) :: i,ieeeok,iinfo,imax,indd,inddd,inde,indee,indibl,indifl, &
           indisp,indiwo,indtau,indwk,indwkn,iscale,j,jj,liwmin,llwork,llwrkn,lwkopt, &
                     lwmin,nb,nsplit
           real(dp) :: abstll,anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           ieeeok = la_ilaenv(10,'DSYEVR','N',1,2,3,4)
           lower = la_lsame(uplo,'L')
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lquery = ((lwork == -1) .or. (liwork == -1))
           lwmin = max(1,26*n)
           liwmin = max(1,10*n)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -8
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -9
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -10
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -15
              else if (lwork < lwmin .and. .not. lquery) then
                 info = -18
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -20
              end if
           end if
           if (info == 0) then
              nb = la_ilaenv(1,'DSYTRD',uplo,n,-1,-1,-1)
              nb = max(nb,la_ilaenv(1,'DORMTR',uplo,n,-1,-1,-1))
              lwkopt = max((nb + 1)*n,lwmin)
              work(1) = lwkopt
              iwork(1) = liwmin
           end if
           if (info /= 0) then
              call la_xerbla('DSYEVR',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) then
              work(1) = 1
              return
           end if
           if (n == 1) then
              work(1) = 7
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = a(1,1)
              else
                 if (vl < a(1,1) .and. vu >= a(1,1)) then
                    m = 1
                    w(1) = a(1,1)
                 end if
              end if
              if (wantz) then
                 z(1,1) = one
                 isuppz(1) = 1
                 isuppz(2) = 1
              end if
              return
           end if
           ! get machine constants.
           safmin = la_dlamch('SAFE MINIMUM')
           eps = la_dlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           abstll = abstol
           if (valeig) then
              vll = vl
              vuu = vu
           end if
           anrm = la_dlansy('M',uplo,n,a,lda,work)
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              if (lower) then
                 do j = 1,n
                    call la_dscal(n - j + 1,sigma,a(j,j),1)
                 end do
              else
                 do j = 1,n
                    call la_dscal(j,sigma,a(1,j),1)
                 end do
              end if
              if (abstol > 0) abstll = abstol*sigma
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! initialize indices into workspaces.  note: the iwork indices are
           ! used only if la_dsterf or la_dstemr fail.
           ! work(indtau:indtau+n-1) stores the scalar factors of the
           ! elementary reflectors used in la_dsytrd.
           indtau = 1
           ! work(indd:indd+n-1) stores the tridiagonal's diagonal entries.
           indd = indtau + n
           ! work(inde:inde+n-1) stores the off-diagonal entries of the
           ! tridiagonal matrix from la_dsytrd.
           inde = indd + n
           ! work(inddd:inddd+n-1) is a copy of the diagonal entries over
           ! -written by la_dstemr (the la_dsterf path copies the diagonal to w).
           inddd = inde + n
           ! work(indee:indee+n-1) is a copy of the off-diagonal entries over
           ! -written while computing the eigenvalues in la_dsterf and la_dstemr.
           indee = inddd + n
           ! indwk is the starting offset of the left-over workspace, and
           ! llwork is the remaining workspace size.
           indwk = indee + n
           llwork = lwork - indwk + 1
           ! iwork(indibl:indibl+m-1) corresponds to iblock in la_dstebz and
           ! stores the block indices of each of the m<=n eigenvalues.
           indibl = 1
           ! iwork(indisp:indisp+nsplit-1) corresponds to isplit in la_dstebz and
           ! stores the starting and finishing indices of each block.
           indisp = indibl + n
           ! iwork(indifl:indifl+n-1) stores the indices of eigenvectors
           ! that corresponding to eigenvectors that fail to converge in
           ! la_dstein.  this information is discarded; if any fail, the driver
           ! returns info > 0.
           indifl = indisp + n
           ! indiwo is the offset of the remaining integer workspace.
           indiwo = indifl + n
           ! call la_dsytrd to reduce symmetric matrix to tridiagonal form.
           call la_dsytrd(uplo,n,a,lda,work(indd),work(inde),work(indtau),work( &
                     indwk),llwork,iinfo)
           ! if all eigenvalues are desired
           ! then call la_dsterf or la_dstemr and la_dormtr.
           if ((alleig .or. (indeig .and. il == 1 .and. iu == n)) .and. ieeeok == 1) then
              if (.not. wantz) then
                 call la_dcopy(n,work(indd),1,w,1)
                 call la_dcopy(n - 1,work(inde),1,work(indee),1)
                 call la_dsterf(n,w,work(indee),info)
              else
                 call la_dcopy(n - 1,work(inde),1,work(indee),1)
                 call la_dcopy(n,work(indd),1,work(inddd),1)
                 if (abstol <= two*n*eps) then
                    tryrac = .true.
                 else
                    tryrac = .false.
                 end if
                 call la_dstemr(jobz,'A',n,work(inddd),work(indee),vl,vu,il,iu,m, &
                            w,z,ldz,n,isuppz,tryrac,work(indwk),lwork,iwork,liwork,info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_dstemr.
                 if (wantz .and. info == 0) then
                    indwkn = inde
                    llwrkn = lwork - indwkn + 1
                    call la_dormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                               indwkn),llwrkn,iinfo)
                 end if
              end if
              if (info == 0) then
                 ! everything worked.  skip la_dstebz/la_dstein.  iwork(:) are
                 ! undefined.
                 m = n
                 go to 30
              end if
              info = 0
           end if
           ! otherwise, call la_dstebz and, if eigenvectors are desired, la_dstein.
           ! also call la_dstebz and la_dstein if la_dstemr fails.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           call la_dstebz(range,order,n,vll,vuu,il,iu,abstll,work(indd),work(inde &
           ),m,nsplit,w,iwork(indibl),iwork(indisp),work(indwk),iwork(indiwo),info)

           if (wantz) then
              call la_dstein(n,work(indd),work(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,work(indwk),iwork(indiwo),iwork(indifl),info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_dstein.
              indwkn = inde
              llwrkn = lwork - indwkn + 1
              call la_dormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                        indwkn),llwrkn,iinfo)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
        ! jump here if la_dstemr/la_dstein succeeded.
        30 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_dscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.  note: we do not sort the ifail portion of iwork.
           ! it may not be initialized (if la_dstemr/la_dstein succeeded), and we do
           ! not return this detailed information to the user.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    w(i) = w(j)
                    w(j) = tmp1
                    call la_dswap(n,z(1,i),1,z(1,j),1)
                 end if
              end do
           end if
           ! set work(1) to optimal workspace size.
           work(1) = lwkopt
           iwork(1) = liwmin
           return
     end subroutine la_dsyevr
#ifdef LA_WITH_XDP
     !> XSYEVR: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric matrix A.  Eigenvalues and eigenvectors can be
     !> selected by specifying either a range of values or a range of
     !> indices for the desired eigenvalues.
     !> XSYEVR first reduces the matrix A to tridiagonal form T with a call
     !> to XSYTRD.  Then, whenever possible, XSYEVR calls XSTEMR to compute
     !> the eigenspectrum using Relatively Robust Representations.  XSTEMR
     !> computes eigenvalues by the dqds algorithm, while orthogonal
     !> eigenvectors are computed from various "good" L D L^T representations
     !> (also known as Relatively Robust Representations). Gram-Schmidt
     !> orthogonalization is avoided as far as possible. More specifically,
     !> the various steps of the algorithm are as follows.
     !> For each unreduced block (submatrix) of T,
     !> (a) Compute T - sigma I  = L D L^T, so that L and D
     !> define all the wanted eigenvalues to high relative accuracy.
     !> This means that small relative changes in the entries of D and L
     !> cause only small relative changes in the eigenvalues and
     !> eigenvectors. The standard (unfactored) representation of the
     !> tridiagonal matrix T does not have this property in general.
     !> (b) Compute the eigenvalues to suitable accuracy.
     !> If the eigenvectors are desired, the algorithm attains full
     !> accuracy of the computed eigenvalues only right before
     !> the corresponding vectors have to be computed, see steps c) and d).
     !> (c) For each cluster of close eigenvalues, select a new
     !> shift close to the cluster, find a new factorization, and refine
     !> the shifted eigenvalues to suitable accuracy.
     !> (d) For each eigenvalue with a large enough relative separation compute
     !> the corresponding eigenvector by forming a rank revealing twisted
     !> factorization. Go back to (c) for any clusters that remain.
     !> The desired accuracy of the output can be specified by the input
     !> parameter ABSTOL.
     !> For more details, see XSTEMR's documentation and:
     !> - Inderjit S. Dhillon and Beresford N. Parlett: "Multiple representations
     !> to compute orthogonal eigenvectors of symmetric tridiagonal matrices,"
     !> Linear Algebra and its Applications, 387(1), pp. 1-28, August 2004.
     !> - Inderjit Dhillon and Beresford Parlett: "Orthogonal Eigenvectors and
     !> Relative Gaps," SIAM Journal on Matrix Analysis and Applications, Vol. 25,
     !> 2004.  Also LAPACK Working Note 154.
     !> - Inderjit Dhillon: "A new O(n^2) algorithm for the symmetric
     !> tridiagonal eigenvalue/eigenvector problem",
     !> Computer Science Division Technical Report No. UCB/CSD-97-971,
     !> UC Berkeley, May 1997.
     !> Note 1 : XSYEVR calls XSTEMR when the full spectrum is requested
     !> on machines which conform to the ieee-754 floating point standard.
     !> XSYEVR calls XSTEBZ and XSTEIN on non-ieee machines and
     !> when partial spectrum requests are made.
     !> Normal execution of XSTEMR may create NaNs and infinities and
     !> hence may abort due to a floating point exception in environments
     !> which do not handle NaNs and infinities in the ieee standard default
     !> manner.

     subroutine la_xsyevr(jobz,range,uplo,n,a,lda,vl,vu,il,iu,abstol,m,w,z,ldz, &
               isuppz,work,lwork,iwork,liwork,info)
        use la_constants_xdp,only:zero,one,two
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,iu,lda,ldz,liwork,lwork,n
           integer(ilp),intent(out) :: info,m
           real(xdp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: isuppz(*),iwork(*)
           real(xdp),intent(inout) :: a(lda,*)
           real(xdp),intent(out) :: w(*),work(*),z(ldz,*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,lower,lquery,valeig,wantz,tryrac
           character :: order
           integer(ilp) :: i,ieeeok,iinfo,imax,indd,inddd,inde,indee,indibl,indifl, &
           indisp,indiwo,indtau,indwk,indwkn,iscale,j,jj,liwmin,llwork,llwrkn,lwkopt, &
                     lwmin,nb,nsplit
           real(xdp) :: abstll,anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           ieeeok = la_ilaenv(10,'XSYEVR','N',1,2,3,4)
           lower = la_lsame(uplo,'L')
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lquery = ((lwork == -1) .or. (liwork == -1))
           lwmin = max(1,26*n)
           liwmin = max(1,10*n)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -8
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -9
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -10
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -15
              else if (lwork < lwmin .and. .not. lquery) then
                 info = -18
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -20
              end if
           end if
           if (info == 0) then
              nb = la_ilaenv(1,'XSYTRD',uplo,n,-1,-1,-1)
              nb = max(nb,la_ilaenv(1,'XORMTR',uplo,n,-1,-1,-1))
              lwkopt = max((nb + 1)*n,lwmin)
              work(1) = lwkopt
              iwork(1) = liwmin
           end if
           if (info /= 0) then
              call la_xerbla('XSYEVR',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) then
              work(1) = 1
              return
           end if
           if (n == 1) then
              work(1) = 7
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = a(1,1)
              else
                 if (vl < a(1,1) .and. vu >= a(1,1)) then
                    m = 1
                    w(1) = a(1,1)
                 end if
              end if
              if (wantz) then
                 z(1,1) = one
                 isuppz(1) = 1
                 isuppz(2) = 1
              end if
              return
           end if
           ! get machine constants.
           safmin = la_xlamch('SAFE MINIMUM')
           eps = la_xlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           abstll = abstol
           if (valeig) then
              vll = vl
              vuu = vu
           end if
           anrm = la_xlansy('M',uplo,n,a,lda,work)
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              if (lower) then
                 do j = 1,n
                    call la_xscal(n - j + 1,sigma,a(j,j),1)
                 end do
              else
                 do j = 1,n
                    call la_xscal(j,sigma,a(1,j),1)
                 end do
              end if
              if (abstol > 0) abstll = abstol*sigma
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! initialize indices into workspaces.  note: the iwork indices are
           ! used only if la_xsterf or la_xstemr fail.
           ! work(indtau:indtau+n-1) stores the scalar factors of the
           ! elementary reflectors used in la_xsytrd.
           indtau = 1
           ! work(indd:indd+n-1) stores the tridiagonal's diagonal entries.
           indd = indtau + n
           ! work(inde:inde+n-1) stores the off-diagonal entries of the
           ! tridiagonal matrix from la_xsytrd.
           inde = indd + n
           ! work(inddd:inddd+n-1) is a copy of the diagonal entries over
           ! -written by la_xstemr (the la_xsterf path copies the diagonal to w).
           inddd = inde + n
           ! work(indee:indee+n-1) is a copy of the off-diagonal entries over
           ! -written while computing the eigenvalues in la_xsterf and la_xstemr.
           indee = inddd + n
           ! indwk is the starting offset of the left-over workspace, and
           ! llwork is the remaining workspace size.
           indwk = indee + n
           llwork = lwork - indwk + 1
           ! iwork(indibl:indibl+m-1) corresponds to iblock in la_xstebz and
           ! stores the block indices of each of the m<=n eigenvalues.
           indibl = 1
           ! iwork(indisp:indisp+nsplit-1) corresponds to isplit in la_xstebz and
           ! stores the starting and finishing indices of each block.
           indisp = indibl + n
           ! iwork(indifl:indifl+n-1) stores the indices of eigenvectors
           ! that corresponding to eigenvectors that fail to converge in
           ! la_xstein.  this information is discarded; if any fail, the driver
           ! returns info > 0.
           indifl = indisp + n
           ! indiwo is the offset of the remaining integer workspace.
           indiwo = indifl + n
           ! call la_xsytrd to reduce symmetric matrix to tridiagonal form.
           call la_xsytrd(uplo,n,a,lda,work(indd),work(inde),work(indtau),work( &
                     indwk),llwork,iinfo)
           ! if all eigenvalues are desired
           ! then call la_xsterf or la_xstemr and la_xormtr.
           if ((alleig .or. (indeig .and. il == 1 .and. iu == n)) .and. ieeeok == 1) then
              if (.not. wantz) then
                 call la_xcopy(n,work(indd),1,w,1)
                 call la_xcopy(n - 1,work(inde),1,work(indee),1)
                 call la_xsterf(n,w,work(indee),info)
              else
                 call la_xcopy(n - 1,work(inde),1,work(indee),1)
                 call la_xcopy(n,work(indd),1,work(inddd),1)
                 if (abstol <= two*n*eps) then
                    tryrac = .true.
                 else
                    tryrac = .false.
                 end if
                 call la_xstemr(jobz,'A',n,work(inddd),work(indee),vl,vu,il,iu,m, &
                            w,z,ldz,n,isuppz,tryrac,work(indwk),lwork,iwork,liwork,info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_xstemr.
                 if (wantz .and. info == 0) then
                    indwkn = inde
                    llwrkn = lwork - indwkn + 1
                    call la_xormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                               indwkn),llwrkn,iinfo)
                 end if
              end if
              if (info == 0) then
                 ! everything worked.  skip la_xstebz/la_xstein.  iwork(:) are
                 ! undefined.
                 m = n
                 go to 30
              end if
              info = 0
           end if
           ! otherwise, call la_xstebz and, if eigenvectors are desired, la_xstein.
           ! also call la_xstebz and la_xstein if la_xstemr fails.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           call la_xstebz(range,order,n,vll,vuu,il,iu,abstll,work(indd),work(inde &
           ),m,nsplit,w,iwork(indibl),iwork(indisp),work(indwk),iwork(indiwo),info)

           if (wantz) then
              call la_xstein(n,work(indd),work(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,work(indwk),iwork(indiwo),iwork(indifl),info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_xstein.
              indwkn = inde
              llwrkn = lwork - indwkn + 1
              call la_xormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                        indwkn),llwrkn,iinfo)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
        ! jump here if la_xstemr/la_xstein succeeded.
        30 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_xscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.  note: we do not sort the ifail portion of iwork.
           ! it may not be initialized (if la_xstemr/la_xstein succeeded), and we do
           ! not return this detailed information to the user.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    w(i) = w(j)
                    w(j) = tmp1
                    call la_xswap(n,z(1,i),1,z(1,j),1)
                 end if
              end do
           end if
           ! set work(1) to optimal workspace size.
           work(1) = lwkopt
           iwork(1) = liwmin
           return
     end subroutine la_xsyevr
#endif
#ifdef LA_WITH_QP
     !> QSYEVR: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric matrix A.  Eigenvalues and eigenvectors can be
     !> selected by specifying either a range of values or a range of
     !> indices for the desired eigenvalues.
     !> QSYEVR first reduces the matrix A to tridiagonal form T with a call
     !> to QSYTRD.  Then, whenever possible, QSYEVR calls QSTEMR to compute
     !> the eigenspectrum using Relatively Robust Representations.  QSTEMR
     !> computes eigenvalues by the dqds algorithm, while orthogonal
     !> eigenvectors are computed from various "good" L D L^T representations
     !> (also known as Relatively Robust Representations). Gram-Schmidt
     !> orthogonalization is avoided as far as possible. More specifically,
     !> the various steps of the algorithm are as follows.
     !> For each unreduced block (submatrix) of T,
     !> (a) Compute T - sigma I  = L D L^T, so that L and D
     !> define all the wanted eigenvalues to high relative accuracy.
     !> This means that small relative changes in the entries of D and L
     !> cause only small relative changes in the eigenvalues and
     !> eigenvectors. The standard (unfactored) representation of the
     !> tridiagonal matrix T does not have this property in general.
     !> (b) Compute the eigenvalues to suitable accuracy.
     !> If the eigenvectors are desired, the algorithm attains full
     !> accuracy of the computed eigenvalues only right before
     !> the corresponding vectors have to be computed, see steps c) and d).
     !> (c) For each cluster of close eigenvalues, select a new
     !> shift close to the cluster, find a new factorization, and refine
     !> the shifted eigenvalues to suitable accuracy.
     !> (d) For each eigenvalue with a large enough relative separation compute
     !> the corresponding eigenvector by forming a rank revealing twisted
     !> factorization. Go back to (c) for any clusters that remain.
     !> The desired accuracy of the output can be specified by the input
     !> parameter ABSTOL.
     !> For more details, see QSTEMR's documentation and:
     !> - Inderjit S. Dhillon and Beresford N. Parlett: "Multiple representations
     !> to compute orthogonal eigenvectors of symmetric tridiagonal matrices,"
     !> Linear Algebra and its Applications, 387(1), pp. 1-28, August 2004.
     !> - Inderjit Dhillon and Beresford Parlett: "Orthogonal Eigenvectors and
     !> Relative Gaps," SIAM Journal on Matrix Analysis and Applications, Vol. 25,
     !> 2004.  Also LAPACK Working Note 154.
     !> - Inderjit Dhillon: "A new O(n^2) algorithm for the symmetric
     !> tridiagonal eigenvalue/eigenvector problem",
     !> Computer Science Division Technical Report No. UCB/CSD-97-971,
     !> UC Berkeley, May 1997.
     !> Note 1 : QSYEVR calls QSTEMR when the full spectrum is requested
     !> on machines which conform to the ieee-754 floating point standard.
     !> QSYEVR calls QSTEBZ and QSTEIN on non-ieee machines and
     !> when partial spectrum requests are made.
     !> Normal execution of QSTEMR may create NaNs and infinities and
     !> hence may abort due to a floating point exception in environments
     !> which do not handle NaNs and infinities in the ieee standard default
     !> manner.

     subroutine la_qsyevr(jobz,range,uplo,n,a,lda,vl,vu,il,iu,abstol,m,w,z,ldz, &
               isuppz,work,lwork,iwork,liwork,info)
        use la_constants_qp,only:zero,one,two
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,iu,lda,ldz,liwork,lwork,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: isuppz(*),iwork(*)
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,lower,lquery,valeig,wantz,tryrac
           character :: order
           integer(ilp) :: i,ieeeok,iinfo,imax,indd,inddd,inde,indee,indibl,indifl, &
           indisp,indiwo,indtau,indwk,indwkn,iscale,j,jj,liwmin,llwork,llwrkn,lwkopt, &
                     lwmin,nb,nsplit
           real(qp) :: abstll,anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           ieeeok = la_ilaenv(10,'QSYEVR','N',1,2,3,4)
           lower = la_lsame(uplo,'L')
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lquery = ((lwork == -1) .or. (liwork == -1))
           lwmin = max(1,26*n)
           liwmin = max(1,10*n)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -8
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -9
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -10
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -15
              else if (lwork < lwmin .and. .not. lquery) then
                 info = -18
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -20
              end if
           end if
           if (info == 0) then
              nb = la_ilaenv(1,'QSYTRD',uplo,n,-1,-1,-1)
              nb = max(nb,la_ilaenv(1,'QORMTR',uplo,n,-1,-1,-1))
              lwkopt = max((nb + 1)*n,lwmin)
              work(1) = lwkopt
              iwork(1) = liwmin
           end if
           if (info /= 0) then
              call la_xerbla('QSYEVR',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) then
              work(1) = 1
              return
           end if
           if (n == 1) then
              work(1) = 7
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = a(1,1)
              else
                 if (vl < a(1,1) .and. vu >= a(1,1)) then
                    m = 1
                    w(1) = a(1,1)
                 end if
              end if
              if (wantz) then
                 z(1,1) = one
                 isuppz(1) = 1
                 isuppz(2) = 1
              end if
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           abstll = abstol
           if (valeig) then
              vll = vl
              vuu = vu
           end if
           anrm = la_qlansy('M',uplo,n,a,lda,work)
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              if (lower) then
                 do j = 1,n
                    call la_qscal(n - j + 1,sigma,a(j,j),1)
                 end do
              else
                 do j = 1,n
                    call la_qscal(j,sigma,a(1,j),1)
                 end do
              end if
              if (abstol > 0) abstll = abstol*sigma
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! initialize indices into workspaces.  note: the iwork indices are
           ! used only if la_qsterf or la_qstemr fail.
           ! work(indtau:indtau+n-1) stores the scalar factors of the
           ! elementary reflectors used in la_qsytrd.
           indtau = 1
           ! work(indd:indd+n-1) stores the tridiagonal's diagonal entries.
           indd = indtau + n
           ! work(inde:inde+n-1) stores the off-diagonal entries of the
           ! tridiagonal matrix from la_qsytrd.
           inde = indd + n
           ! work(inddd:inddd+n-1) is a copy of the diagonal entries over
           ! -written by la_qstemr (the la_qsterf path copies the diagonal to w).
           inddd = inde + n
           ! work(indee:indee+n-1) is a copy of the off-diagonal entries over
           ! -written while computing the eigenvalues in la_qsterf and la_qstemr.
           indee = inddd + n
           ! indwk is the starting offset of the left-over workspace, and
           ! llwork is the remaining workspace size.
           indwk = indee + n
           llwork = lwork - indwk + 1
           ! iwork(indibl:indibl+m-1) corresponds to iblock in la_qstebz and
           ! stores the block indices of each of the m<=n eigenvalues.
           indibl = 1
           ! iwork(indisp:indisp+nsplit-1) corresponds to isplit in la_qstebz and
           ! stores the starting and finishing indices of each block.
           indisp = indibl + n
           ! iwork(indifl:indifl+n-1) stores the indices of eigenvectors
           ! that corresponding to eigenvectors that fail to converge in
           ! la_qstein.  this information is discarded; if any fail, the driver
           ! returns info > 0.
           indifl = indisp + n
           ! indiwo is the offset of the remaining integer workspace.
           indiwo = indifl + n
           ! call la_qsytrd to reduce symmetric matrix to tridiagonal form.
           call la_qsytrd(uplo,n,a,lda,work(indd),work(inde),work(indtau),work( &
                     indwk),llwork,iinfo)
           ! if all eigenvalues are desired
           ! then call la_qsterf or la_qstemr and la_qormtr.
           if ((alleig .or. (indeig .and. il == 1 .and. iu == n)) .and. ieeeok == 1) then
              if (.not. wantz) then
                 call la_qcopy(n,work(indd),1,w,1)
                 call la_qcopy(n - 1,work(inde),1,work(indee),1)
                 call la_qsterf(n,w,work(indee),info)
              else
                 call la_qcopy(n - 1,work(inde),1,work(indee),1)
                 call la_qcopy(n,work(indd),1,work(inddd),1)
                 if (abstol <= two*n*eps) then
                    tryrac = .true.
                 else
                    tryrac = .false.
                 end if
                 call la_qstemr(jobz,'A',n,work(inddd),work(indee),vl,vu,il,iu,m, &
                            w,z,ldz,n,isuppz,tryrac,work(indwk),lwork,iwork,liwork,info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_qstemr.
                 if (wantz .and. info == 0) then
                    indwkn = inde
                    llwrkn = lwork - indwkn + 1
                    call la_qormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                               indwkn),llwrkn,iinfo)
                 end if
              end if
              if (info == 0) then
                 ! everything worked.  skip la_qstebz/la_qstein.  iwork(:) are
                 ! undefined.
                 m = n
                 go to 30
              end if
              info = 0
           end if
           ! otherwise, call la_qstebz and, if eigenvectors are desired, la_qstein.
           ! also call la_qstebz and la_qstein if la_qstemr fails.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           call la_qstebz(range,order,n,vll,vuu,il,iu,abstll,work(indd),work(inde &
           ),m,nsplit,w,iwork(indibl),iwork(indisp),work(indwk),iwork(indiwo),info)

           if (wantz) then
              call la_qstein(n,work(indd),work(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,work(indwk),iwork(indiwo),iwork(indifl),info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_qstein.
              indwkn = inde
              llwrkn = lwork - indwkn + 1
              call la_qormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                        indwkn),llwrkn,iinfo)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
        ! jump here if la_qstemr/la_qstein succeeded.
        30 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.  note: we do not sort the ifail portion of iwork.
           ! it may not be initialized (if la_qstemr/la_qstein succeeded), and we do
           ! not return this detailed information to the user.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    w(i) = w(j)
                    w(j) = tmp1
                    call la_qswap(n,z(1,i),1,z(1,j),1)
                 end if
              end do
           end if
           ! set work(1) to optimal workspace size.
           work(1) = lwkopt
           iwork(1) = liwmin
           return
     end subroutine la_qsyevr
#endif

     !> CHB2ST_KERNELS: is an internal routine used by the CHETRD_HB2ST
     !> subroutine.

     pure subroutine la_chb2st_kernels(uplo,wantz,ttype,st,ed,sweep,n,nb,ib,a,lda, &
               v,tau,ldvt,work)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           logical(lk),intent(in) :: wantz
           integer(ilp),intent(in) :: ttype,st,ed,sweep,n,nb,ib,lda,ldvt
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: v(*),tau(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i,j1,j2,lm,ln,vpos,taupos,dpos,ofdpos,ajeter
           complex(sp) :: ctmp
           ! Intrinsic Functions
           intrinsic :: conjg,mod
           ! Executable Statements
           ajeter = ib + ldvt
           upper = la_lsame(uplo,'U')
           if (upper) then
               dpos = 2*nb + 1
               ofdpos = 2*nb
           else
               dpos = 1
               ofdpos = 2
           end if
           ! upper case
           if (upper) then
               if (wantz) then
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               else
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               end if
               if (ttype == 1) then
                   lm = ed - st + 1
                   v(vpos) = cone
                   do i = 1,lm - 1
                       v(vpos + i) = conjg(a(ofdpos - i,st + i))
                       a(ofdpos - i,st + i) = czero
                   end do
                   ctmp = conjg(a(ofdpos,st))
                   call la_clarfg(lm,ctmp,v(vpos + 1),1,tau(taupos))
                   a(ofdpos,st) = ctmp
                   lm = ed - st + 1
                   call la_clarfy(uplo,lm,v(vpos),1,conjg(tau(taupos)),a(dpos,st) &
                             ,lda - 1,work)
               end if
               if (ttype == 3) then
                   lm = ed - st + 1
                   call la_clarfy(uplo,lm,v(vpos),1,conjg(tau(taupos)),a(dpos,st) &
                             ,lda - 1,work)
               end if
               if (ttype == 2) then
                   j1 = ed + 1
                   j2 = min(ed + nb,n)
                   ln = ed - st + 1
                   lm = j2 - j1 + 1
                   if (lm > 0) then
                       call la_clarfx('LEFT',ln,lm,v(vpos),conjg(tau(taupos)),a( &
                                 dpos - nb,j1),lda - 1,work)
                       if (wantz) then
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       else
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       end if
                       v(vpos) = cone
                       do i = 1,lm - 1
                           v(vpos + i) = conjg(a(dpos - nb - i,j1 + i))
                           a(dpos - nb - i,j1 + i) = czero
                       end do
                       ctmp = conjg(a(dpos - nb,j1))
                       call la_clarfg(lm,ctmp,v(vpos + 1),1,tau(taupos))
                       a(dpos - nb,j1) = ctmp
                       call la_clarfx('RIGHT',ln - 1,lm,v(vpos),tau(taupos),a(dpos - nb + &
                                 1,j1),lda - 1,work)
                   end if
               end if
           ! lower case
           else
               if (wantz) then
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               else
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               end if
               if (ttype == 1) then
                   lm = ed - st + 1
                   v(vpos) = cone
                   do i = 1,lm - 1
                       v(vpos + i) = a(ofdpos + i,st - 1)
                       a(ofdpos + i,st - 1) = czero
                   end do
                   call la_clarfg(lm,a(ofdpos,st - 1),v(vpos + 1),1,tau(taupos))

                   lm = ed - st + 1
                   call la_clarfy(uplo,lm,v(vpos),1,conjg(tau(taupos)),a(dpos,st) &
                             ,lda - 1,work)
               end if
               if (ttype == 3) then
                   lm = ed - st + 1
                   call la_clarfy(uplo,lm,v(vpos),1,conjg(tau(taupos)),a(dpos,st) &
                             ,lda - 1,work)
               end if
               if (ttype == 2) then
                   j1 = ed + 1
                   j2 = min(ed + nb,n)
                   ln = ed - st + 1
                   lm = j2 - j1 + 1
                   if (lm > 0) then
                       call la_clarfx('RIGHT',lm,ln,v(vpos),tau(taupos),a(dpos + nb, &
                                 st),lda - 1,work)
                       if (wantz) then
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       else
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       end if
                       v(vpos) = cone
                       do i = 1,lm - 1
                           v(vpos + i) = a(dpos + nb + i,st)
                           a(dpos + nb + i,st) = czero
                       end do
                       call la_clarfg(lm,a(dpos + nb,st),v(vpos + 1),1,tau(taupos))

                       call la_clarfx('LEFT',lm,ln - 1,v(vpos),conjg(tau(taupos)),a( &
                                 dpos + nb - 1,st + 1),lda - 1,work)
                   end if
               end if
           end if
           return
     end subroutine la_chb2st_kernels
