                       end do
                       ctmp = conjg(a(dpos - nb,j1))
                       call la_zlarfg(lm,ctmp,v(vpos + 1),1,tau(taupos))
                       a(dpos - nb,j1) = ctmp
                       call la_zlarfx('RIGHT',ln - 1,lm,v(vpos),tau(taupos),a(dpos - nb + &
                                 1,j1),lda - 1,work)
                   end if
               end if
           ! lower case
           else
               if (wantz) then
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               else
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
