                   do i = 1,lm - 1
                       v(vpos + i) = a(ofdpos + i,st - 1)
                       a(ofdpos + i,st - 1) = czero
                   end do
                   call la_zlarfg(lm,a(ofdpos,st - 1),v(vpos + 1),1,tau(taupos))

                   lm = ed - st + 1
                   call la_zlarfy(uplo,lm,v(vpos),1,conjg(tau(taupos)),a(dpos,st) &
                             ,lda - 1,work)
               end if
               if (ttype == 3) then
                   lm = ed - st + 1
                   call la_zlarfy(uplo,lm,v(vpos),1,conjg(tau(taupos)),a(dpos,st) &
                             ,lda - 1,work)
               end if
               if (ttype == 2) then
