                       ! a := a - v * w**h - w * v**h
                    call la_yher2(uplo,n - i,-cone,a(i + 1,i),1,tau(i),1,a(i + 1,i + 1) &
                              ,lda)
                 else
                    a(i + 1,i + 1) = real(a(i + 1,i + 1),KIND=xdp)
                 end if
                 a(i + 1,i) = e(i)
                 d(i) = real(a(i,i),KIND=xdp)
                 tau(i) = taui
              end do
              d(n) = real(a(n,n),KIND=xdp)
           end if
           return
     end subroutine la_yhetd2
#endif
#ifdef LA_WITH_QP
     !> WHETD2: reduces a complex Hermitian matrix A to real symmetric
     !> tridiagonal form T by a unitary similarity transformation:
     !> Q**H * A * Q = T.

     pure subroutine la_whetd2(uplo,n,a,lda,d,e,tau,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           real(qp),intent(out) :: d(*),e(*)
           complex(qp),intent(inout) :: a(lda,*)
           complex(qp),intent(out) :: tau(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i
           complex(qp) :: alpha,taui
           ! Intrinsic Functions
           intrinsic :: real,max,min
           ! Executable Statements
           ! test the input parameters
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('WHETD2',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) return
           if (upper) then
              ! reduce the upper triangle of a
              a(n,n) = real(a(n,n),KIND=qp)
              do i = n - 1,1,-1
                 ! generate elementary reflector h(i) = i - tau * v * v**h
                 ! to annihilate a(1:i-1,i+1)
                 alpha = a(i,i + 1)
                 call la_wlarfg(i,alpha,a(1,i + 1),1,taui)
                 e(i) = real(alpha,KIND=qp)
                 if (taui /= czero) then
                    ! apply h(i) from both sides to a(1:i,1:i)
                    a(i,i + 1) = cone
                    ! compute  x := tau * a * v  storing x in tau(1:i)
                    call la_whemv(uplo,i,taui,a,lda,a(1,i + 1),1,czero,tau,1)

