                       ! a := a - v * w**h - w * v**h
                    call la_wher2(uplo,i,-cone,a(1,i + 1),1,tau,1,a,lda)
                 else
                    a(i,i) = real(a(i,i),KIND=qp)
                 end if
                 a(i,i + 1) = e(i)
                 d(i + 1) = real(a(i + 1,i + 1),KIND=qp)
                 tau(i) = taui
              end do
              d(1) = real(a(1,1),KIND=qp)
           else
