              if (n > 1) then
                 ! generate q(2:n,2:n)
                 call la_zungqr(n - 1,n - 1,n - 1,a(2,2),lda,tau,work,lwork,iinfo)

              end if
           end if
           work(1) = lwkopt
           return
     end subroutine la_zungtr
