           indd = 1
           inde = indd + n
           indrwk = inde + n
           indtau = 1
           indwrk = indtau + n
           llwork = lwork - indwrk + 1
           call la_chetrd(uplo,n,a,lda,rwork(indd),rwork(inde),work(indtau),work( &
                      indwrk),llwork,iinfo)
