           if ((alleig .or. test) .and. (abstol <= zero)) then
              call la_xcopy(n,rwork(indd),1,w,1)
              indee = indrwk + 2*n
              if (.not. wantz) then
                 call la_xcopy(n - 1,rwork(inde),1,rwork(indee),1)
                 call la_xsterf(n,w,rwork(indee),info)
              else
                 call la_ylacpy('A',n,n,a,lda,z,ldz)
                 call la_yungtr(uplo,n,z,ldz,work(indtau),work(indwrk),llwork, &
                           iinfo)
                 call la_xcopy(n - 1,rwork(inde),1,rwork(indee),1)
                 call la_ysteqr(jobz,n,w,rwork(indee),z,ldz,rwork(indrwk),info)

                 if (info == 0) then
                    do i = 1,n
                       ifail(i) = 0
                    end do
                 end if
              end if
              if (info == 0) then
                 m = n
                 go to 40
              end if
              info = 0
           end if
           ! otherwise, call la_xstebz and, if eigenvectors are desired, la_ystein.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           indibl = 1
           indisp = indibl + n
           indiwk = indisp + n
           call la_xstebz(range,order,n,vll,vuu,il,iu,abstll,rwork(indd),rwork( &
           inde),m,nsplit,w,iwork(indibl),iwork(indisp),rwork(indrwk),iwork(indiwk), &
                      info)
           if (wantz) then
              call la_ystein(n,rwork(indd),rwork(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,rwork(indrwk),iwork(indiwk),ifail,info)
              ! apply unitary matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_ystein.
              call la_yunmtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                        indwrk),llwork,iinfo)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           40 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_xscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    itmp1 = iwork(indibl + i - 1)
                    w(i) = w(j)
                    iwork(indibl + i - 1) = iwork(indibl + j - 1)
                    w(j) = tmp1
                    iwork(indibl + j - 1) = itmp1
                    call la_yswap(n,z(1,i),1,z(1,j),1)
                    if (info /= 0) then
                       itmp1 = ifail(i)
                       ifail(i) = ifail(j)
                       ifail(j) = itmp1
                    end if
                 end if
              end do
           end if
           ! set work(1) to optimal complex workspace size.
           work(1) = lwkopt
           return
     end subroutine la_yheevx
#endif
#ifdef LA_WITH_QP
     !> WHEEVX: computes selected eigenvalues and, optionally, eigenvectors
     !> of a complex Hermitian matrix A.  Eigenvalues and eigenvectors can
     !> be selected by specifying either a range of values or a range of
     !> indices for the desired eigenvalues.

     subroutine la_wheevx(jobz,range,uplo,n,a,lda,vl,vu,il,iu,abstol,m,w,z,ldz, &
               work,lwork,rwork,iwork,ifail,info)
        use la_constants_qp,only:zero,one,cone
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,iu,lda,ldz,lwork,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: ifail(*),iwork(*)
           real(qp),intent(out) :: rwork(*),w(*)
           complex(qp),intent(inout) :: a(lda,*)
           complex(qp),intent(out) :: work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,lower,lquery,test,valeig,wantz
           character :: order
           integer(ilp) :: i,iinfo,imax,indd,inde,indee,indibl,indisp,indiwk,indrwk, &
                     indtau,indwrk,iscale,itmp1,j,jj,llwork,lwkmin,lwkopt,nb,nsplit
           real(qp) :: abstll,anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: real,max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           lower = la_lsame(uplo,'L')
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lquery = (lwork == -1)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -8
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -9
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -10
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -15
              end if
           end if
           if (info == 0) then
              if (n <= 1) then
                 lwkmin = 1
                 work(1) = lwkmin
              else
                 lwkmin = 2*n
                 nb = la_ilaenv(1,'WHETRD',uplo,n,-1,-1,-1)
                 nb = max(nb,la_ilaenv(1,'WUNMTR',uplo,n,-1,-1,-1))
                 lwkopt = max(1, (nb + 1)*n)
                 work(1) = lwkopt
              end if
              if (lwork < lwkmin .and. .not. lquery) info = -17
           end if
           if (info /= 0) then
              call la_xerbla('WHEEVX',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) then
              return
           end if
           if (n == 1) then
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = real(a(1,1),KIND=qp)
              else if (valeig) then
                 if (vl < real(a(1,1),KIND=qp) .and. vu >= real(a(1,1),KIND=qp)) then
                    m = 1
                    w(1) = real(a(1,1),KIND=qp)
                 end if
              end if
              if (wantz) z(1,1) = cone
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           abstll = abstol
           if (valeig) then
              vll = vl
              vuu = vu
           end if
           anrm = la_wlanhe('M',uplo,n,a,lda,rwork)
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              if (lower) then
                 do j = 1,n
                    call la_wqscal(n - j + 1,sigma,a(j,j),1)
                 end do
              else
                 do j = 1,n
                    call la_wqscal(j,sigma,a(1,j),1)
                 end do
              end if
              if (abstol > 0) abstll = abstol*sigma
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! call la_whetrd to reduce hermitian matrix to tridiagonal form.
           indd = 1
           inde = indd + n
           indrwk = inde + n
           indtau = 1
           indwrk = indtau + n
           llwork = lwork - indwrk + 1
           call la_whetrd(uplo,n,a,lda,rwork(indd),rwork(inde),work(indtau),work( &
                      indwrk),llwork,iinfo)
           ! if all eigenvalues are desired and abstol is less than or equal to
           ! zero, then call la_qsterf or la_wungtr and la_wsteqr.  if this fails for
           ! some eigenvalue, then try la_qstebz.
           test = .false.
           if (indeig) then
              if (il == 1 .and. iu == n) then
                 test = .true.
              end if
           end if
           if ((alleig .or. test) .and. (abstol <= zero)) then
              call la_qcopy(n,rwork(indd),1,w,1)
              indee = indrwk + 2*n
              if (.not. wantz) then
                 call la_qcopy(n - 1,rwork(inde),1,rwork(indee),1)
                 call la_qsterf(n,w,rwork(indee),info)
              else
                 call la_wlacpy('A',n,n,a,lda,z,ldz)
                 call la_wungtr(uplo,n,z,ldz,work(indtau),work(indwrk),llwork, &
                           iinfo)
                 call la_qcopy(n - 1,rwork(inde),1,rwork(indee),1)
                 call la_wsteqr(jobz,n,w,rwork(indee),z,ldz,rwork(indrwk),info)

                 if (info == 0) then
                    do i = 1,n
                       ifail(i) = 0
                    end do
                 end if
              end if
              if (info == 0) then
                 m = n
                 go to 40
              end if
              info = 0
           end if
           ! otherwise, call la_qstebz and, if eigenvectors are desired, la_wstein.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           indibl = 1
           indisp = indibl + n
           indiwk = indisp + n
           call la_qstebz(range,order,n,vll,vuu,il,iu,abstll,rwork(indd),rwork( &
           inde),m,nsplit,w,iwork(indibl),iwork(indisp),rwork(indrwk),iwork(indiwk), &
                      info)
           if (wantz) then
              call la_wstein(n,rwork(indd),rwork(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,rwork(indrwk),iwork(indiwk),ifail,info)
              ! apply unitary matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_wstein.
              call la_wunmtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                        indwrk),llwork,iinfo)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           40 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    itmp1 = iwork(indibl + i - 1)
                    w(i) = w(j)
                    iwork(indibl + i - 1) = iwork(indibl + j - 1)
                    w(j) = tmp1
                    iwork(indibl + j - 1) = itmp1
                    call la_wswap(n,z(1,i),1,z(1,j),1)
                    if (info /= 0) then
                       itmp1 = ifail(i)
                       ifail(i) = ifail(j)
                       ifail(j) = itmp1
                    end if
                 end if
              end do
           end if
           ! set work(1) to optimal complex workspace size.
           work(1) = lwkopt
           return
     end subroutine la_wheevx
#endif

     !> CHEGV: computes all the eigenvalues, and optionally, the eigenvectors
     !> of a complex generalized Hermitian-definite eigenproblem, of the form
     !> A*x=(lambda)*B*x,  A*Bx=(lambda)*x,  or B*A*x=(lambda)*x.
     !> Here A and B are assumed to be Hermitian and B is also
     !> positive definite.

     subroutine la_chegv(itype,jobz,uplo,n,a,lda,b,ldb,w,work,lwork,rwork,info)
        use la_constants_sp

        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: itype,lda,ldb,lwork,n
           ! Array Arguments
           real(sp),intent(out) :: rwork(*),w(*)
           complex(sp),intent(inout) :: a(lda,*),b(ldb,*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,upper,wantz
           character :: trans
           integer(ilp) :: lwkopt,nb,neig
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1)
           info = 0
           if (itype < 1 .or. itype > 3) then
              info = -1
           else if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -2
           else if (.not. (upper .or. la_lsame(uplo,'L'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else if (ldb < max(1,n)) then
              info = -8
           end if
           if (info == 0) then
              nb = la_ilaenv(1,'CHETRD',uplo,n,-1,-1,-1)
              lwkopt = max(1, (nb + 1)*n)
              work(1) = lwkopt
              if (lwork < max(1,2*n - 1) .and. .not. lquery) then
                 info = -11
              end if
           end if
           if (info /= 0) then
              call la_xerbla('CHEGV ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! form a cholesky factorization of b.
           call la_cpotrf(uplo,n,b,ldb,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem and solve.
           call la_chegst(itype,uplo,n,a,lda,b,ldb,info)
           call la_cheev(jobz,uplo,n,a,lda,w,work,lwork,rwork,info)
           if (wantz) then
              ! backtransform eigenvectors to the original problem.
              neig = n
              if (info > 0) neig = info - 1
              if (itype == 1 .or. itype == 2) then
                 ! for a*x=(lambda)*b*x and a*b*x=(lambda)*x;
                 ! backtransform eigenvectors: x = inv(l)**h*y or inv(u)*y
                 if (upper) then
                    trans = 'N'
                 else
                    trans = 'C'
                 end if
                 call la_ctrsm('LEFT',uplo,trans,'NON-UNIT',n,neig,cone,b,ldb,a,lda &
                           )
              else if (itype == 3) then
                 ! for b*a*x=(lambda)*x;
                 ! backtransform eigenvectors: x = l*y or u**h*y
                 if (upper) then
                    trans = 'C'
                 else
                    trans = 'N'
                 end if
                 call la_ctrmm('LEFT',uplo,trans,'NON-UNIT',n,neig,cone,b,ldb,a,lda &
                           )
              end if
           end if
           work(1) = lwkopt
           return
     end subroutine la_chegv
