                 liwmin = 1
              end if
           end if
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (kd < 0) then
              info = -4
           else if (ldab < kd + 1) then
              info = -6
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -9
           end if
           if (info == 0) then
              work(1) = lwmin
              rwork(1) = lrwmin
              iwork(1) = liwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -11
              else if (lrwork < lrwmin .and. .not. lquery) then
                 info = -13
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -15
              end if
           end if
           if (info /= 0) then
              call la_xerbla('CHBEVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              w(1) = real(ab(1,1),KIND=sp)
              if (wantz) z(1,1) = cone
              return
           end if
           ! get machine constants.
           safmin = la_slamch('SAFE MINIMUM')
           eps = la_slamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = sqrt(bignum)
