           if (iscale == 1) then
              if (info == 0) then
                 imax = n
              else
                 imax = info - 1
              end if
              call la_sscal(imax,one/sigma,w,1)
           end if
           work(1) = lwmin
           rwork(1) = lrwmin
           iwork(1) = liwmin
           return
     end subroutine la_chbevd
