           safmin = la_slamch('SAFE MINIMUM')
           eps = la_slamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
