              vll = vl
              vuu = vu
           else
              vll = zero
              vuu = zero
           end if
           anrm = la_clanhb('M',uplo,n,kd,ab,ldab,rwork)
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
