           indd = 1
           inde = indd + n
           indrwk = inde + n
           indwrk = 1
           call la_chbtrd(jobz,uplo,n,kd,ab,ldab,rwork(indd),rwork(inde),q,ldq, &
                     work(indwrk),iinfo)
