              call la_cstedc('I',n,w,rwork(inde),work,n,work(indwk2),llwk2,rwork( &
                        indwrk),llrwk,iwork,liwork,info)
              call la_cgemm('N','N',n,n,n,cone,z,ldz,work,n,czero,work(indwk2), &
                        n)
              call la_clacpy('A',n,n,work(indwk2),n,z,ldz)
           end if
