                 call la_zcopy(n,z(1,j),1,work(1),1)
                 call la_zgemv('N',n,n,cone,q,ldq,work,1,czero,z(1,j),1)
              end do
           end if
           30 continue
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.
