                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    itmp1 = iwork(indibl + i - 1)
                    w(i) = w(j)
                    iwork(indibl + i - 1) = iwork(indibl + j - 1)
                    w(j) = tmp1
                    iwork(indibl + j - 1) = itmp1
                    call la_zswap(n,z(1,i),1,z(1,j),1)
                    if (info /= 0) then
